const defaults = {
  tunnel_quality_score: 0,
  tunnel_friction_level: 'unknown',
  tunnel_friction_reasons: '',
  tunnel_recommendations: '',
  tunnel_estimated_conversion_rate: 0
};

const items = $input.all();

const safeAll = (nodeName) => {
  try { return $(nodeName).all().map((x) => x.json || {}); } catch (_) { return []; }
};

const parseSources = [
  ...safeAll('Parse Landing Page Content'),
  ...safeAll('Prepare Landing Page Extraction')
];

const byAdId = new Map();
for (const s of parseSources) {
  if (s && s.ad_id !== undefined && s.ad_id !== null && String(s.ad_id).trim() !== '') {
    byAdId.set(String(s.ad_id), s);
  }
}

const parsePossibleJson = (value) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  try { return JSON.parse(trimmed); } catch (_) {
    const match = trimmed.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try { return JSON.parse(match[0]); } catch (_) { return null; }
  }
};

const normalize = (current) => {
  let tunnelData = { ...defaults };
  let source = current.output ?? current;

  if (typeof source === 'string') {
    const parsed = parsePossibleJson(source);
    source = parsed || source;
  }

  if (source && typeof source === 'object' && !Array.isArray(source)) {
    tunnelData = { ...tunnelData, ...source };
  }

  const reasons = Array.isArray(tunnelData.tunnel_friction_reasons)
    ? tunnelData.tunnel_friction_reasons.join(', ')
    : (tunnelData.tunnel_friction_reasons || '');

  const recommendations = Array.isArray(tunnelData.tunnel_recommendations)
    ? tunnelData.tunnel_recommendations.join(', ')
    : (tunnelData.tunnel_recommendations || '');

  return {
    tunnel_quality_score: tunnelData.tunnel_quality_score ?? 0,
    tunnel_friction_level: tunnelData.tunnel_friction_level || 'unknown',
    tunnel_friction_reasons: reasons,
    tunnel_recommendations: recommendations,
    tunnel_estimated_conversion_rate: tunnelData.tunnel_estimated_conversion_rate ?? 0
  };
};

const pickSource = (item, index) => {
  const current = item.json || {};
  if (current.ad_id || current.brand || current.form_type || current.landing_page_url) return current;

  const currentOutput = current.output;
  if (currentOutput && typeof currentOutput === 'object' && !Array.isArray(currentOutput)) {
    const id = currentOutput.ad_id;
    if (id !== undefined && id !== null) {
      const key = String(id);
      if (byAdId.has(key)) return byAdId.get(key);
    }
  }

  const pairIndex = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : null;
  if (typeof pairIndex === 'number' && parseSources[pairIndex]) return parseSources[pairIndex];

  return parseSources[index] || {};
};

return items.map((item, index) => {
  const current = item.json || {};
  const source = pickSource(item, index);
  const normalized = normalize(current);

  return {
    json: {
      ...source,
      ...current,
      ...normalized,
      final_form_type: current.final_form_type || source.final_form_type || current.form_type || source.form_type || 'external_landing_page',
      form_type: current.form_type || source.form_type || current.final_form_type || source.final_form_type || 'external_landing_page',
      pipeline_item_id: current.pipeline_item_id || source.pipeline_item_id || '',
      ad_id: current.ad_id || source.ad_id || '',
      brand: current.brand || source.brand || '',
      landing_page_url: current.landing_page_url || source.landing_page_url || source.website_url || current.website_url || '',
      headline: current.headline || source.headline || '',
      body_text: current.body_text || source.body_text || '',
      visual_url: current.visual_url || source.visual_url || ''
    }
  };
});

