return items.map((item, index) => {
  const current = item.json || {};
  const candidates = current.candidates;
  const response = (candidates && candidates[0] && candidates[0].content && candidates[0].content.parts && candidates[0].content.parts[0] && candidates[0].content.parts[0].text)
    || current.text
    || 'No content';

  let source = null;
  if (current.pipeline_item_id && byPipelineId.has(String(current.pipeline_item_id))) source = byPipelineId.get(String(current.pipeline_item_id));
  if (!source && current.ad_id !== undefined && current.ad_id !== null && byAdId.has(String(current.ad_id))) source = byAdId.get(String(current.ad_id));
  if (!source) {
    const pairedIndex = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : index;
    source = sourceItems[pairedIndex] || null;
  }

  const original = source || current;
  return { json: { ...original, video_analysis: response } };
});

