const sourcePool = [
  ...safeAll('Keep Ad Image'),
  ...safeAll('No Image')
];

const byPipelineId = new Map();
const byAdId = new Map();
for (const s of sourcePool) {
  if (s && s.pipeline_item_id) byPipelineId.set(String(s.pipeline_item_id), s);
