const pickSource = (current, item, index) => {
  if (current.pipeline_item_id && byPipelineId.has(String(current.pipeline_item_id))) return byPipelineId.get(String(current.pipeline_item_id));
  if (current.ad_id !== undefined && current.ad_id !== null && byAdId.has(String(current.ad_id))) return byAdId.get(String(current.ad_id));
  const pairIndex = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : null;
  if (typeof pairIndex === 'number' && sourcePool[pairIndex]) return sourcePool[pairIndex];
  return sourcePool[index] || {};
};

const toAiOutput = (current) => {
  if (current.output && typeof current.output === 'object' && !Array.isArray(current.output)) return current.output;
  if (typeof current.output === 'string') return parsePossibleJson(current.output) || { raw_text: current.output };
  if (typeof current.text === 'string') return parsePossibleJson(current.text) || { raw_text: current.text };
  if (typeof current.response === 'string') return parsePossibleJson(current.response) || { raw_text: current.response };
  return {};
};

const pickText = (...vals) => {
  for (const v of vals) {
    if (typeof v === 'string' && v.trim() !== '') return v.trim();
  }
  return '';
};

const extractFromRawText = (raw, key) => {
  if (typeof raw !== 'string' || !raw) return '';
  const re = new RegExp('\"' + key + '\"\s*:\s*\"([\s\S]*?)\"', 'i');
  const m = raw.match(re);
  if (!m || !m[1]) return '';
  return m[1].trim();
};

return items.map((item, index) => {
  const current = item.json || {};
  const source = pickSource(current, item, index);
  const ai = toAiOutput(current);
  const raw = (typeof current.text === 'string' && current.text)
    || (typeof current.output === 'string' && current.output)
    || (ai && typeof ai.raw_text === 'string' ? ai.raw_text : '');

  return {
    json: {
      ...source,
      ...current,
      output: ai,
      pipeline_item_id: current.pipeline_item_id || source.pipeline_item_id || '',
      ad_id: current.ad_id || source.ad_id || '',
      hook_type: pickText(ai.hook_type, extractFromRawText(raw, 'hook_type'), current.hook_type, source.hook_type),
      why_it_works: pickText(ai.why_it_works, extractFromRawText(raw, 'why_it_works'), current.why_it_works, source.why_it_works),
      takeaway_1: pickText(ai.takeaway_1, extractFromRawText(raw, 'takeaway_1'), current.takeaway_1, source.takeaway_1),
      takeaway_2: pickText(ai.takeaway_2, extractFromRawText(raw, 'takeaway_2'), current.takeaway_2, source.takeaway_2),
      takeaway_3: pickText(ai.takeaway_3, extractFromRawText(raw, 'takeaway_3'), current.takeaway_3, source.takeaway_3),
      hook_de_sortie: pickText(ai.hook_de_sortie, extractFromRawText(raw, 'hook_de_sortie'), current.hook_de_sortie, source.hook_de_sortie),
      tunnel_friction_reasons: pickText(ai.tunnel_friction_reasons, extractFromRawText(raw, 'tunnel_friction_reasons'), current.tunnel_friction_reasons, source.tunnel_friction_reasons),
      tunnel_recommendations: pickText(ai.tunnel_recommendations, extractFromRawText(raw, 'tunnel_recommendations'), current.tunnel_recommendations, source.tunnel_recommendations)
    }
  };
});

return $input.all().map((item) => {
  const binaryData = item.binary.data;

  if (!binaryData) {
    return { json: item.json || {} };
  }

  return {
    json: item.json || {},
    binary: {
      data: {
        ...binaryData,
        mimeType: 'video/mp4',
        fileExtension: 'mp4',
        fileName: binaryData.fileName || 'video.mp4'
      }
    }
  };
});

