const items = $input.all();
const seen = new Set();
const out = [];

for (const item of items) {
  const j = item.json || {};
  const videoUrl = typeof j.video_url === 'string' ? j.video_url.trim() : '';
  const hasVideo = j.has_video === true || videoUrl !== '';
  if (!hasVideo) continue;

  const key = j.pipeline_item_id || j.ad_id || '';
  if (key && seen.has(String(key))) continue;
  if (key) seen.add(String(key));

  out.push({ json: { ...j, has_video: true, video_url: videoUrl } });
}

return out;
